import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class AsyncPipelineDemo {
    private static final ExecutorService pool = Executors.newFixedThreadPool(4);

    public static CompletableFuture<String> fetchUserData(String userId) {
        return CompletableFuture.supplyAsync(() -> {
            if (userId == null || userId.isBlank()) {
                throw new IllegalArgumentException("Invalid User ID");
            }
            return "User:" + userId;
        }, pool);
    }

    public static CompletableFuture<Double> fetchUserCreditScore(String user) {
        return CompletableFuture.supplyAsync(() -> 750.0, pool);
    }

    public static void main(String[] args) {
        CompletableFuture<String> pipeline = fetchUserData("U123")
            .thenCompose(user -> fetchUserCreditScore(user)
                .thenCombine(CompletableFuture.completedFuture(2.0), (score, multiplier) -> score * multiplier)
                .thenApply(finalScore -> "User U123 Final Score: " + finalScore))
            .exceptionally(ex -> "Fallback processing due to: " + ex.getMessage());

        System.out.println(pipeline.join());
        pool.shutdown();
    }
}
